css:
:scope { width: min(100%, 1296px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 12; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i2 { grid-column: 14 / span 3; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i3 { grid-column: 1 / span 12; grid-row: 5 / span 19; font-family: var(--os-font-heading); font-size: 72.6px; font-weight: 700; line-height: 1; letter-spacing: -0.022em; color: var(--os-color-heading); }
.gx__i4 { grid-column: 14 / span 10; grid-row: 6 / span 7; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i5 { grid-column: 14 / span 10; grid-row: 15 / span 7; font-family: var(--os-font-label); font-size: 14.9px; font-weight: 700; line-height: 1.43; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-background); }
.gx__i6 { grid-column: 1 / span 10; grid-row: 26 / span 17; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i7 { grid-column: 14 / span 10; grid-row: 25 / span 5; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 400; line-height: 1.4; letter-spacing: 0.16em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i8 { grid-column: 14 / span 10; grid-row: 36 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i9 { grid-column: 14 / span 10; grid-row: 41 / span 6; font-family: var(--os-font-body); font-size: 17px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i10 { grid-column: 1 / span 10; grid-row: 45 / span 17; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i11 { grid-column: 14 / span 10; grid-row: 48 / span 6; font-family: var(--os-font-body); font-size: 17px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i12 { grid-column: 14 / span 10; grid-row: 56 / span 6; font-family: var(--os-font-body); font-size: 17px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; color: var(--os-color-heading); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 58px; }
  .gx__i4 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i5 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i7 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i8 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i9 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i10 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i11 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i12 { font-family: var(--os-font-body); font-size: 14px; }
}
